pub fn medians(xs: List[Int], k: Int) -> List[Float] {
  var out: List[Float] = []
  let n = xs.len()
  if k < 1 or k > n {
    return out
  }
  let mid = k / 2
  for i in range(0, n - k + 1) {
    let sorted = xs.slice(i, i + k).sort()
    if k % 2 == 1 {
      out = out.push(sorted.get_or(mid, 0).to_float())
    } else {
      let lo = sorted.get_or(mid - 1, 0)
      let hi = sorted.get_or(mid, 0)
      out = out.push((lo + hi).to_float() / 2.0)
    }
  }
  return out
}
